const initialCode=`def two_sum(nums, target):
    seen = {}

    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], i]
        seen[num] = i

    return []`;

function useTheme(){
 const [light,setLight]=useState(()=>localStorage.getItem("ca-theme")==="light");
 useEffect(()=>{document.documentElement.dataset.theme=light?"light":"dark";localStorage.setItem("ca-theme",light?"light":"dark")},[light]);
 return [light,setLight];
}
function Brand(){return <Link to="/" className="brand"><span className="brand-mark"><Code2 size={18}/></span><b>Code</b><b className="brand-muted">Arena</b></Link>}
function Badge({children,type=""}){return <span className={"badge "+type.toLowerCase().replaceAll(" ","-")}>{children}</span>}
function Button({children,primary=false,small=false,className="",...p}){return <button className={`btn ${primary?"primary":""} ${small?"small":""} ${className}`} {...p}>{children}</button>}
function Toast({message,onClose}){return <div className="toast"><CheckCircle2 size={17}/><span>{message}</span><button onClick={onClose}><X size={14}/></button></div>}

