 return <div className="app"><aside className={`sidebar ${collapsed?"collapsed":""} ${mobile?"open":""}`}><div className="side-brand"><Brand/><button onClick={()=>setCollapsed(!collapsed)}><PanelLeft size={16}/></button></div><div className="role-chip"><div className={`role-dot ${role}`}>{role==="student"?<User/>:role==="faculty"?<GraduationCap/>:<ShieldCheck/>}</div>{!collapsed&&<div><b>{title}</b><span>{role==="student"?"Kritarth Joshi":role==="faculty"?"Dr. Neha Sharma":"System Admin"}</span></div>}</div><nav className="side-nav">{nav.map(([to,label,I])=><NavLink end={to==="/dashboard"||to==="/faculty"||to==="/admin"} to={to} key={to} onClick={()=>setMobile(false)}><I/><span>{label}</span></NavLink>)}</nav><div className="side-bottom">{role==="student"&&<NavLink to="/profile"><User/><span>Profile</span></NavLink>}<NavLink to="/settings"><Settings/><span>Settings</span></NavLink><button onClick={()=>location.href="/"}><LogOut/><span>Sign out</span></button></div></aside><div className="app-main"><header className="app-header"><button className="mobile-only icon-btn" onClick={()=>setMobile(!mobile)}><Menu/></button><div className="global-search"><Search/><input placeholder={role==="student"?"Search problems, contests...":"Search students, exams, reports..."}/><kbd>⌘ K</kbd></div><div className="header-actions"><button className="icon-btn"><Bell/><i/></button><button className="theme-toggle" onClick={()=>setLight(!light)}>{light?<Moon/>:<Sun/>}</button><div className="header-user"><div className="avatar">{role==="student"?"KJ":role==="faculty"?"NS":"AD"}</div><div><b>{role==="student"?"Kritarth":role==="faculty"?"Dr. Neha":"Admin"}</b><span>{role}</span></div><ChevronDown size={14}/></div></div></header><main className="app-content">{children}</main></div></div>
