function PageHead({eyebrow,title,description,children}){return <div className="page-head"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div><div className="page-head-actions">{children}</div></div>}
function Stat({label,value,delta,icon}){return <div className="stat"><div className="stat-label"><span>{label}</span><i>{icon}</i></div><strong>{value}</strong><small>{delta}</small></div>}
function Panel({title,sub,children,action}){return <section className="panel"><div className="panel-head"><div><h3>{title}</h3>{sub&&<p>{sub}</p>}</div>{action}</div>{children}</section>}
function Dashboard(){
 return <><PageHead eyebrow="Student dashboard" title="Good morning, Kritarth 👋" description="Your coding progress is moving in the right direction."><Link to="/contests" className="btn primary"><Trophy size={16}/> Join contest</Link></PageHead><div className="stats"><Stat label="Problems solved" value="128" delta="+12 this month" icon={<CheckCircle2/>}/><Stat label="Current rank" value="#4" delta="↑ 8 positions" icon={<Trophy/>}/><Stat label="Accuracy" value="91.4%" delta="+4.2% this month" icon={<Target/>}/><Stat label="Contest rating" value="1,987" delta="+126 this season" icon={<Zap/>}/></div><div className="grid-2"><Panel title="Performance overview" sub="Score trend over the last 7 days" action={<select><option>Last 7 days</option><option>Last 30 days</option></select>}><div className="chart"><ResponsiveContainer width="100%" height={260}><AreaChart data={activity}><defs><linearGradient id="scorefill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#6978ff" stopOpacity=".3"/><stop offset="100%" stopColor="#6978ff" stopOpacity="0"/></linearGradient></defs><CartesianGrid strokeDasharray="3 3" stroke="var(--grid)"/><XAxis dataKey="day" stroke="var(--muted)" fontSize={10}/><YAxis stroke="var(--muted)" fontSize={10}/><Tooltip contentStyle={{background:"var(--tooltip)",border:"1px solid var(--line)",borderRadius:10,color:"var(--text)"}}/><Area type="monotone" dataKey="score" stroke="#6978ff" fill="url(#scorefill)" strokeWidth={3}/></AreaChart></ResponsiveContainer></div></Panel><Panel title="Smart insights" sub="Personalized from your activity"><div className="insights"><Insight text="Your accuracy improved by 12% this month."/><Insight text="You solve medium problems 24% faster than average."/><Insight text="Try 2 more hard graph problems this week."/><Link to="/performance" className="text-link">View analytics <ArrowRight size={14}/></Link></div></Panel></div><div className="grid-2"><Panel title="Live & upcoming contests" sub="Your next challenges" action={<Link to="/contests" className="text-link">View all</Link>}>{contests.slice(0,3).map(c=><ContestLine c={c} key={c.id}/>)}</Panel><Panel title="Recent submissions" sub="Latest activity" action={<Link to="/submissions" className="text-link">View all</Link>}>{["Two Sum","Number of Islands","Merge Intervals","LRU Cache"].map((x,i)=><div className="simple-row" key={x}><div className="status-circle"><CheckCircle2/></div><div><b>{x}</b><span>{i%2?"C++":"Python"} · {i+1}h ago</span></div><Badge type={i===2?"wrong-answer":"accepted"}>{i===2?"Wrong Answer":"Accepted"}</Badge></div>)}</Panel></div></>
}
function Insight({text}){return <div className="insight"><Sparkles/><span>{text}</span></div>}
function ContestLine({c}){return <Link to={`/contests/${c.id}`} className="contest-line"><div className="contest-symbol"><Trophy/></div><div><b>{c.name}</b><span>{c.problems} problems · {c.participants.toLocaleString()} participants</span></div><Badge type={c.status}>{c.status}</Badge><ArrowRight size={15}/></Link>}

function Contests(){
 return <><PageHead eyebrow="Student · Competitions" title="Contests" description="Join live competitions, scheduled exams and practice events."><Button><Filter size={15}/> Filters</Button></PageHead><div className="toolbar"><div className="tabs"><button className="active">All</button><button>Live</button><button>Upcoming</button><button>Completed</button></div><div className="search-field"><Search/><input placeholder="Search contests"/></div></div><div className="contest-cards">{contests.map(c=><div className="contest-card" key={c.id}><div className="contest-top"><div className="contest-symbol big"><Trophy/></div><Badge type={c.status}>{c.status}</Badge></div><h3>{c.name}</h3><p>Curated coding challenges designed to measure real problem-solving ability.</p><div className="contest-data"><span><BookOpen/> {c.problems} problems</span><span><Users/> {c.participants.toLocaleString()}</span><span><Clock3/> {c.duration}</span></div><div className="contest-bottom"><span>{c.difficulty}</span><Link to={`/contests/${c.id}`} className="btn primary small">{c.status==="Live"?"Enter contest":"View contest"} <ArrowRight size={14}/></Link></div></div>)}</div></>
}
function Problems(){
 const [q,setQ]=useState("");const [d,setD]=useState("All");const list=problems.filter(p=>(p.title+p.topic).toLowerCase().includes(q.toLowerCase())&&(d==="All"||p.difficulty===d));
 return <><PageHead eyebrow="Student · Practice" title="Problem library" description="Practice by topic, difficulty and skill."/><div className="toolbar"><div className="search-field wide"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search problems or topics"/></div><div className="tabs">{["All","Easy","Medium","Hard"].map(x=><button key={x} className={d===x?"active":""} onClick={()=>setD(x)}>{x}</button>)}</div></div><Panel title={`${list.length} problems`} sub="Curated institutional problem bank"><div className="table-wrap"><table><thead><tr><th>Problem</th><th>Difficulty</th><th>Topic</th><th>Acceptance</th><th>Points</th><th/></tr></thead><tbody>{list.map(p=><tr key={p.id}><td><Link to={`/problems/${p.id}`} className="table-problem"><span className="number">{p.id}</span><b>{p.title}</b></Link></td><td><Badge type={p.difficulty}>{p.difficulty}</Badge></td><td>{p.topic}</td><td>{p.acceptance}%</td><td>{p.points}</td><td><Link to={`/problems/${p.id}`} className="icon-btn"><ArrowRight/></Link></td></tr>)}</tbody></table></div></Panel></>
}
function ContestDetails(){
 const {id}=useParams();const c=contests.find(x=>x.id==id)||contests[0];
 return <><PageHead eyebrow="Contest" title={c.name} description={`${c.difficulty} · ${c.problems} problems · ${c.duration}`}><div className="countdown"><Clock3/> {c.status==="Live"?"00:24:17":"Starts "+c.time}</div></PageHead><div className="grid-2 contest-detail"><Panel title="Problems" sub="Choose a challenge to begin"><div>{problems.slice(0,c.problems).map((p,i)=><Link className="problem-line" to={`/problems/${p.id}`} key={p.id}><span className="letter">{String.fromCharCode(65+i)}</span><div><b>{p.title}</b><span>{p.topic} · {p.points} points</span></div><Badge type={p.difficulty}>{p.difficulty}</Badge>{i<2?<CheckCircle2 className="success"/>:<ChevronRight/>}</Link>)}</div></Panel><Panel title="Contest snapshot" sub="Your live standing"><div className="score-big">420 <small>/ 1000</small></div><div className="progress"><span style={{width:"42%"}}/></div>{[["Your rank","#47 / 1,248"],["Solved","2 / 5"],["Time remaining","24m 17s"],["Smart score","86.2"]].map(([a,b])=><div className="info-line" key={a}><span>{a}</span><b>{b}</b></div>)}<Link to="/leaderboard" className="btn full">View leaderboard <ArrowRight size={15}/></Link></Panel></div></>
}
function Problem(){
 const {id}=useParams();const p=problems.find(x=>x.id==id)||problems[0];const [code,setCode]=useState(initialCode);const [status,setStatus]=useState("");const [busy,setBusy]=useState(false);
 const run=()=>{setBusy(true);setStatus("Running test cases...");setTimeout(()=>{setBusy(false);setStatus("Accepted · 12/12 tests passed · 42 ms · 14.2 MB")},1000)};
 return <div className="ide"><div className="ide-bar"><Link to="/problems"><ArrowLeft size={15}/> Problems</Link><div><b>{p.title}</b><Badge type={p.difficulty}>{p.difficulty}</Badge></div><div className="ide-actions"><select><option>Python</option><option>C++</option><option>Java</option><option>JavaScript</option></select><Button small onClick={run}><Play size={14}/> Run</Button><Button primary small onClick={run}>{busy?"Submitting...":"Submit"} <Send size={14}/></Button></div></div><div className="ide-main"><article className="problem-statement"><div className="tabs"><button className="active">Description</button><button>Editorial</button></div><h1>{p.title}</h1><div className="problem-tags"><Badge type={p.difficulty}>{p.difficulty}</Badge><span>{p.topic}</span><span>{p.points} points</span></div><h3>Problem statement</h3><p>Given an array of integers <code>nums</code> and an integer <code>target</code>, return indices of the two numbers such that they add up to target. You may assume each input has exactly one solution.</p><h3>Constraints</h3><ul><li>2 ≤ nums.length ≤ 10,000</li><li>-10⁹ ≤ nums[i] ≤ 10⁹</li><li>Each input has exactly one valid answer.</li></ul><h3>Example</h3><pre className="example">Input: nums = [2,7,11,15], target = 9{"\n"}Output: [0,1]</pre></article><div className="code-side"><div className="editor-label"><span><FileCode2/> solution.py</span><span>Python 3.12</span></div><Editor height="100%" language="python" theme={document.documentElement.dataset.theme==="light"?"light":"vs-dark"} value={code} onChange={v=>setCode(v||"")} options={{minimap:{enabled:false},fontSize:14,automaticLayout:true,padding:{top:14},roundedSelection:false}}/><div className="console"><div className="console-tabs"><button className="active">Test cases</button><button>Custom input</button><button>Output</button></div><div className="console-result">{status?<><CheckCircle2 className="success"/><div><b>{status.split(" · ")[0]}</b><span>{status.includes(" · ")?status.split(" · ").slice(1).join(" · "):"Please wait..."}</span></div></>:<div className="test-cases"><span>✓ Case 1</span><span>✓ Case 2</span><span>✓ Case 3</span><span>✓ Case 4</span></div>}</div></div></div></div></div>
}
function Playground(){return <div className="ide"><div className="ide-bar"><div><Terminal size={16}/> <b>Code Playground</b></div><div className="ide-actions"><select><option>Python</option><option>C++</option><option>Java</option></select><Button small><Upload size={14}/> Save</Button><Button primary small><Play size={14}/> Run</Button></div></div><div className="playground"><aside><b>EXPLORER</b><span>▾ workspace</span><span className="file active">▣ main.py</span><span className="file">▣ utils.py</span><span className="file">▣ README.md</span></aside><div><Editor height="100%" language="python" theme={document.documentElement.dataset.theme==="light"?"light":"vs-dark"} defaultValue={initialCode} options={{minimap:{enabled:false},fontSize:14,automaticLayout:true}}/></div><section className="play-console"><b><Terminal size={14}/> Console</b><pre>CodeArena Python 3.12{"\n"}Ready to execute your code.{"\n"}<span>$</span> _</pre></section></div></div>
}
function Leaderboard(){
 return <><PageHead eyebrow="Competition" title="Leaderboard" description="Transparent performance rankings across the institution."><Button><Filter size={15}/> Filters</Button></PageHead><div className="podium">{leaderboard.slice(0,3).map((x,i)=><div className={`podium-card ${i===0?"second":i===1?"first":"third"}`} key={x.rank}><span>{i===0?"🥈":i===1?"🥇":"🥉"}</span><div className="avatar large">{x.name.split(" ").map(a=>a[0]).join("")}</div><b>#{x.rank} {x.name}</b><strong>{x.score}</strong><small>Smart score {x.smart}</small></div>)}</div><Panel title="Institution leaderboard" sub="Smart ranking enabled"><div className="table-wrap"><table><thead><tr><th>Rank</th><th>Coder</th><th>Score</th><th>Solved</th><th>Accuracy</th><th>Time</th><th>Smart score</th></tr></thead><tbody>{leaderboard.map(x=><tr className={x.name.includes("Kritarth")?"highlight":""} key={x.rank}><td>#{x.rank}</td><td><div className="person"><div className="avatar">{x.name.split(" ").map(a=>a[0]).join("")}</div><b>{x.name}</b>{x.name.includes("Kritarth")&&<Badge>YOU</Badge>}</div></td><td>{x.score}</td><td>{x.solved}</td><td>{x.accuracy}%</td><td>{x.time}</td><td><b className="accent">{x.smart}</b></td></tr>)}</tbody></table></div></Panel><div className="smart-callout"><BrainCircuit/><div><b>Smart ranking</b><p>Rankings combine accuracy, time efficiency, problem difficulty and submission patterns to produce a more balanced performance score.</p></div></div></>
}
