function AdminAudit(){return <><PageHead eyebrow="Administrator · Security" title="Audit & security" description="Monitor access, role changes and sensitive platform actions."><Badge type="accepted">All systems operational</Badge></PageHead><div className="stats"><Stat label="Security events" value="12" delta="-31% this month" icon={<ShieldCheck/>}/><Stat label="Failed logins" value="47" delta="-18% this week" icon={<KeyRound/>}/><Stat label="Admin sessions" value="18" delta="4 active now" icon={<Users/>}/><Stat label="Audit coverage" value="100%" delta="All critical actions" icon={<CheckCircle2/>}/></div><Panel title="Recent audit events" sub="Latest platform security activity"><div className="audit-list">{["Admin role granted to faculty@university.edu","Contest published: Campus Championship","Password reset requested by STU-2026124","Faculty permissions updated","New administrator session started"].map((x,i)=><div className="audit" key={x}><div><ShieldCheck/></div><span><b>{x}</b><small>{i+2} hours ago · IP 10.24.18.{20+i}</small></span><Badge>{i===0?"Role change":"System"}</Badge></div>)}</div></Panel></>}
function AdminAnalytics(){return <><PageHead eyebrow="Administrator · Intelligence" title="Platform analytics" description="Institution-wide performance, participation and evaluation quality."><Button><Download/> Export report</Button></PageHead><div className="stats"><Stat label="Average score" value="78.6%" delta="+3.8% this term" icon={<Target/>}/><Stat label="Completion rate" value="84.2%" delta="+6.1%" icon={<CheckCircle2/>}/><Stat label="Peak concurrent" value="1,842" delta="Weekly #42" icon={<Users/>}/><Stat label="Evaluation uptime" value="99.96%" delta="Excellent" icon={<Zap/>}/></div><div className="grid-2"><Panel title="Institution activity"><div className="chart"><ResponsiveContainer width="100%" height={300}><LineChart data={activity}><CartesianGrid strokeDasharray="3 3" stroke="var(--grid)"/><XAxis dataKey="day" stroke="var(--muted)"/><YAxis stroke="var(--muted)"/><Tooltip/><Line dataKey="sub" stroke="#6978ff" strokeWidth={3}/></LineChart></ResponsiveContainer></div></Panel><Panel title="Problem difficulty mix"><div className="chart"><ResponsiveContainer width="100%" height={300}><PieChart><Pie data={[{name:"Easy",value:42},{name:"Medium",value:39},{name:"Hard",value:19}]} dataKey="value" nameKey="name" outerRadius={100} label><Cell fill="#56d59c"/><Cell fill="#f0bd54"/><Cell fill="#ff7186"/></Pie><Tooltip/></PieChart></ResponsiveContainer></div></Panel></div></>}
function AdminSettings(){const [light,setLight]=useTheme();return <><PageHead eyebrow="Administrator · System" title="System settings" description="Configure the institution-wide CodeArena environment."/><div className="settings-layout"><nav><button className="active">General</button><button>Authentication</button><button>Evaluation</button><button>Notifications</button><button>Branding</button></nav><Panel title="General settings" sub="Core platform preferences"><label>Institution name<input value="Parul University" readOnly/></label><label>Default contest duration<input value="90 minutes" readOnly/></label><div className="setting-row"><div><b>Theme default</b><span>Choose the default appearance for new users.</span></div><Button onClick={()=>setLight(!light)}>{light?<Moon/>:<Sun/>}{light?"Dark":"Light"} mode</Button></div><div className="setting-row"><div><b>Secure execution</b><span>Sandbox user-submitted code before evaluation.</span></div><span className="switch on"><i/></span></div></Panel></div></>}

function FacultyLayout({children}){return <AppShell role="faculty">{children}</AppShell>}
function AdminLayout({children}){return <AppShell role="admin">{children}</AppShell>}
function StudentLayout({children}){return <AppShell role="student">{children}</AppShell>}

function App(){
 const [light]=useTheme();
 return <Routes>
  <Route path="/" element={<Landing/>}/><Route path="/login" element={<Auth/>}/><Route path="/register" element={<Auth/>}/>
  <Route path="/dashboard" element={<StudentLayout><Dashboard/></StudentLayout>}/><Route path="/contests" element={<StudentLayout><Contests/></StudentLayout>}/><Route path="/contests/:id" element={<StudentLayout><ContestDetails/></StudentLayout>}/><Route path="/problems" element={<StudentLayout><Problems/></StudentLayout>}/><Route path="/problems/:id" element={<Problem/>}/><Route path="/playground" element={<StudentLayout><Playground/></StudentLayout>}/><Route path="/leaderboard" element={<StudentLayout><Leaderboard/></StudentLayout>}/><Route path="/submissions" element={<StudentLayout><Submissions/></StudentLayout>}/><Route path="/performance" element={<StudentLayout><Performance/></StudentLayout>}/><Route path="/profile" element={<StudentLayout><Profile/></StudentLayout>}/><Route path="/settings" element={<StudentLayout><SettingsPage/></StudentLayout>}/>
  <Route path="/faculty" element={<FacultyLayout><FacultyHome/></FacultyLayout>}/><Route path="/faculty/exams" element={<FacultyLayout><FacultyExams/></FacultyLayout>}/><Route path="/faculty/problems" element={<FacultyLayout><FacultyProblems/></FacultyLayout>}/><Route path="/faculty/students" element={<FacultyLayout><FacultyStudents/></FacultyLayout>}/><Route path="/faculty/monitor" element={<FacultyLayout><FacultyMonitor/></FacultyLayout>}/><Route path="/faculty/analytics" element={<FacultyLayout><FacultyAnalytics/></FacultyLayout>}/>
  <Route path="/admin" element={<AdminLayout><AdminHome/></AdminLayout>}/><Route path="/admin/users" element={<AdminLayout><AdminUsers/></AdminLayout>}/><Route path="/admin/contests" element={<AdminLayout><AdminContests/></AdminLayout>}/><Route path="/admin/problems" element={<AdminLayout><AdminProblems/></AdminLayout>}/><Route path="/admin/audit" element={<AdminLayout><AdminAudit/></AdminLayout>}/><Route path="/admin/analytics" element={<AdminLayout><AdminAnalytics/></AdminLayout>}/><Route path="/admin/settings" element={<AdminLayout><AdminSettings/></AdminLayout>}/>
  <Route path="*" element={<NotFound/>}/>
 </Routes>
}
function NotFound(){return <div className="notfound"><Brand/><h1>404</h1><p>That page doesn't exist.</p><Link to="/" className="btn primary">Back home</Link></div>}
createRoot(document.getElementById("root")).render(<BrowserRouter><App/></BrowserRouter>);
